#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string t;
    cin >> t;
    string p;
    cin >> p;

    int m = (int)p.size();
    string u = t + t.substr(0, m - 1);
    string c = p + "#" + u;
    vector<int> pi = prefixFunction(c);
    long long count = 0;
    for (int i = m + 1; i < (int)c.size(); i++) if (pi[i] == m) count++;
    cout << count << "\n";

    return 0;
}

