import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] prefixFunction(String s) {
        int n = s.length();
        int[] pi = new int[n];
        for (int i = 1; i < n; i++) {
            int k = pi[i - 1];
            while (k > 0 && s.charAt(i) != s.charAt(k)) k = pi[k - 1];
            if (s.charAt(i) == s.charAt(k)) k++;
            pi[i] = k;
        }
        return pi;
    }

    public static void main(String[] args) throws IOException {
        String t = next();
        String p = next();

        int m = p.length();
        String u = t + t.substring(0, m - 1);
        String c = p + "#" + u;
        int[] pi = prefixFunction(c);
        long count = 0;
        for (int i = m + 1; i < c.length(); i++) if (pi[i] == m) count++;
        System.out.println(count);
    }
}
